def norm(n):
    n = n.strip().replace('　','').replace(' ','')
    n = re.sub(r'^F-', '', n); n = re.sub(r'-?KY\*?$', '', n); n = n.replace('*','').replace('-創','')
    return n.strip('-')
def build():
    d = {}
    rv = pd.read_csv(RV, dtype=str)
    for code, name in rv[['code','name']].drop_duplicates().itertuples(index=False):
        d.setdefault(norm(name), code)
    sl = pd.read_csv(SL, dtype=str)
    for code, name in sl[['code','name']].itertuples(index=False):
        d[norm(name)] = code
    for k, v in ALIAS.items(): d[norm(k)] = v
    return d
